// Package xml is just enough XML to read UPnP.
//
// What has to be read here is a device description and a handful of SOAP
// envelopes, both flat, both generated by the same small set of router
// firmwares. Finding elements by local name and decoding their text is all
// that is needed, which encoding/xml could do only with a struct per
// response and namespace handling wrapped around it. This is the reader the
// TypeScript version ran against real routers, kept as it was rather than
// swapped for a stricter one that might refuse something they send.
//
// This is deliberately not a general parser. It does not understand
// namespaces properly, nested elements of the same name, or CDATA - none of
// which appear in what UPnP sends.
package xml

import (
	"regexp"
	"strconv"
	"strings"
	"sync"
	"unicode/utf8"
)

var patterns sync.Map // local name → *regexp.Regexp

// pattern matches an element by local name, ignoring whatever namespace
// prefix it carries.
func pattern(name string) *regexp.Regexp {
	if found, ok := patterns.Load(name); ok {
		return found.(*regexp.Regexp)
	}
	local := regexp.QuoteMeta(name)
	compiled := regexp.MustCompile(`(?i)<(?:[\w.-]+:)?` + local + `(?:\s[^>]*)?(?:/>|>([\s\S]*?)</(?:[\w.-]+:)?` + local + `\s*>)`)
	patterns.Store(name, compiled)
	return compiled
}

// Elements is the inner content of every element with this local name, in
// document order.
func Elements(document, name string) []string {
	found := []string{}
	for _, match := range pattern(name).FindAllStringSubmatch(document, -1) {
		found = append(found, match[1])
	}
	return found
}

// Text is the decoded text of the first element with this local name, and
// whether there was one at all.
//
// The two are kept apart because NewRemoteHost and NewPortMappingDescription
// both routinely come back empty, and empty must not be confused with absent.
func Text(document, name string) (string, bool) {
	match := pattern(name).FindStringSubmatch(document)
	if match == nil {
		return "", false
	}
	return Decode(match[1]), true
}

var entity = regexp.MustCompile(`(?i)&(#x?[0-9a-f]+|[a-z]+);`)

var named = map[string]string{"amp": "&", "lt": "<", "gt": ">", "quot": `"`, "apos": "'"}

// Decode decodes XML entities.
//
// Descriptions come back through here, and other tools sharing the router put
// ampersands and quotes in theirs. A description that decodes differently from
// how it was encoded would compare unequal to itself.
//
// A reference that names no character - an unknown entity, a number that is
// not one, a code point that does not exist - is left exactly as it was
// rather than dropped or guessed at.
func Decode(value string) string {
	return entity.ReplaceAllStringFunc(value, func(whole string) string {
		name := whole[1 : len(whole)-1]
		if !strings.HasPrefix(name, "#") {
			if decoded, ok := named[strings.ToLower(name)]; ok {
				return decoded
			}
			return whole
		}
		digits, base := name[1:], 10
		if strings.HasPrefix(strings.ToLower(digits), "x") {
			digits, base = digits[1:], 16
		}
		code, err := strconv.ParseUint(digits, base, 32)
		if err != nil || !utf8.ValidRune(rune(code)) {
			return whole
		}
		return string(rune(code))
	})
}

var escapes = strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&quot;", "'", "&apos;")

// Encode encodes text for an element body.
//
// Container names reach the router inside a rule description, and Docker
// permits characters there that would otherwise close the element early.
func Encode(value string) string { return escapes.Replace(value) }
